    // ── SESSION ──
    private string? _maTruongBo;
    private string? _selectedNamHoc;
    private string? _selectedCapHoc;

    // ── FILTER ──
    private List<KhoiHoc_DTO> _khoiList    = new();
    private List<LopHoc_DTO>  _allLopList  = new();
    private List<LopHoc_DTO>  _lopFiltered = new();
    private int    _selKhoiId  = 0;
    private int    _selLopId   = 0;
    private string _selLopName = "";
    private string _selLopMaLopBo = ""; // dùng cho hGetHocSinhByLop (string malop)

    // ── DATA ──
    private List<ScnDmToDTO>      _toList          = new();
    private List<ScnToHocSinhDTO> _toHocSinhList   = new();
    private List<HocSinhDTO>      _allHsLop        = new(); // tất cả HS lớp
    private bool _isLoading = false;

    // ── TAB ──
    private string _activeTab = "dmto";

    // ── FORM TỔ ──
    private bool       _showToForm  = false;
    private bool       _isSaving    = false;
    private ScnDmToDTO _editTo      = new();
    private string     _toNameError = "";

    // ── DELETE TỔ ──
    private bool        _showDeleteTo    = false;
    private ScnDmToDTO? _deleteToTarget  = null;

    // ── ADD HS MODAL ──
    private bool            _showAddHsModal = false;
    private ScnDmToDTO?     _addHsToTarget  = null;
    private List<HocSinhDTO> _availableHs   = new(); // HS chưa có tổ
    private HashSet<string>  _selectedHsSet = new();

    // ── TOAST ──
    private string _toastMsg  = "";
    private string _toastCss  = "";
    private string _toastIcon = "";
    private System.Threading.CancellationTokenSource? _toastCts;

    // ── LIFECYCLE ──
    protected override async Task OnInitializedAsync()
    {
        _maTruongBo     = await BrowserStorageService.GetMaTruongBoAsync(JS);
        _selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
        _selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");

        _khoiList   = await TruongService.hGetDanhSachKhoi(_maTruongBo ?? "", _selectedCapHoc ?? "1");
        _allLopList = await TruongService.hGetDanhSachLop(_maTruongBo ?? "", _selectedCapHoc ?? "1", _selectedNamHoc ?? "");

        // Auto select khối + lớp đầu tiên
        if (_khoiList.Any())
        {
            _selKhoiId  = _khoiList[0].MaKhoi;
            _lopFiltered = _allLopList.Where(l => l.MaKhoi == _selKhoiId).ToList();
        }
        else _lopFiltered = _allLopList.ToList();

        if (_lopFiltered.Any())
        {
            var firstLop = _lopFiltered[0];
            _selLopId      = firstLop.IdLopBo;
            _selLopName    = firstLop.TenLop;
            _selLopMaLopBo = firstLop.MaLopBo;
        }

        await LoadData();
    }

    private async Task LoadData()
    {
        _isLoading = true;
        StateHasChanged();
        try
        {
            var taskTo = TruongService.hGetDmTo(lopId: _selLopId);
            var taskHS = TruongService.hGetToHocSinh(lopId: _selLopId);
            var taskAllHs = string.IsNullOrEmpty(_selLopMaLopBo)
                ? Task.FromResult(new List<HocSinhDTO>())
                : TruongService.hGetHocSinhByLop(_maTruongBo ?? "", _selLopMaLopBo, _selectedNamHoc ?? "");

            await Task.WhenAll(taskTo, taskHS, taskAllHs);

            _toList        = taskTo.Result;
            _toHocSinhList = taskHS.Result;
            _allHsLop      = taskAllHs.Result;
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error"); }
        finally { _isLoading = false; StateHasChanged(); }
    }

    // ── FILTER EVENTS ──
    private async Task OnKhoiChanged(ChangeEventArgs e)
    {
        _selKhoiId  = int.TryParse(e.Value?.ToString(), out var kv) ? kv : 0;
        _lopFiltered = _selKhoiId == 0
            ? _allLopList.ToList()
            : _allLopList.Where(l => l.MaKhoi == _selKhoiId).ToList();

        if (_lopFiltered.Any())
        {
            var first = _lopFiltered[0];
            _selLopId      = first.IdLopBo;
            _selLopName    = first.TenLop;
            _selLopMaLopBo = first.MaLopBo;
        }
        else { _selLopId = 0; _selLopName = ""; _selLopMaLopBo = ""; }

        await LoadData();
    }

    private async Task OnLopChanged(ChangeEventArgs e)
    {
        _selLopId = int.TryParse(e.Value?.ToString(), out var lv) ? lv : 0;
        var lop   = _lopFiltered.FirstOrDefault(l => l.IdLopBo == _selLopId);
        _selLopName    = lop?.TenLop ?? "";
        _selLopMaLopBo = lop?.MaLopBo ?? "";
        await LoadData();
    }

    private void SetTab(string tab) { _activeTab = tab; StateHasChanged(); }

    // ── FORM TỔ ──
    private void OpenAddToForm()
    {
        _editTo      = new ScnDmToDTO { LopId = _selLopId, KhoiId = _selKhoiId };
        _toNameError = "";
        _showToForm  = true;
    }

    private void OpenEditToForm(ScnDmToDTO to)
    {
        _editTo = new ScnDmToDTO
        {
            Id       = to.Id, TenTo     = to.TenTo, ThuTu     = to.ThuTu,
            MaHsSo   = to.MaHsSo, KhoiId = to.KhoiId, LopId     = to.LopId,
            MaHocKy  = to.MaHocKy, NamHoc  = to.NamHoc,
        };
        _toNameError = "";
        _showToForm  = true;
    }

    private void CloseToForm() { _showToForm = false; _toNameError = ""; }

    private async Task SaveTo()
    {
        if (string.IsNullOrWhiteSpace(_editTo.TenTo)) { _toNameError = "Vui lòng nhập tên tổ!"; return; }
        _editTo.LopId  = _selLopId;
        _editTo.KhoiId = _selKhoiId;
        _editTo.NamHoc = _selectedNamHoc;
        _isSaving = true; StateHasChanged();
        try
        {
            await TruongService.hUpsertDmTo(_editTo);
            CloseToForm();
            await LoadData();
            await ShowToast(_editTo.Id > 0 ? "Cập nhật thành công!" : "Thêm tổ thành công!", "toast-ok", "check_circle");
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error"); }
        finally { _isSaving = false; StateHasChanged(); }
    }

    // ── XÓA TỔ ──
    private void AskDeleteTo(ScnDmToDTO to) { _deleteToTarget = to; _showDeleteTo = true; }

    private async Task ConfirmDeleteTo()
    {
        if (_deleteToTarget == null) return;
        _isSaving = true; StateHasChanged();
        try
        {
            // Xóa toàn bộ HS trong tổ trước
            var members = _toHocSinhList.Where(h => h.TenTo == _deleteToTarget.TenTo).ToList();
            foreach (var m in members)
                await TruongService.hDeleteHocSinhTrongTo(m.Id);
            // Xóa tổ
            await TruongService.hDeleteDmTo(_deleteToTarget.Id);
            _showDeleteTo = false; _deleteToTarget = null;
            await LoadData();
            await ShowToast("Đã xóa tổ!", "toast-ok", "check_circle");
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error"); }
        finally { _isSaving = false; StateHasChanged(); }
    }

    // ── ADD HS VÀO TỔ ──
    private void OpenAddHsModal(ScnDmToDTO to)
    {
        _addHsToTarget  = to;
        _selectedHsSet  = new();

        // HS đã có tổ
        var assignedMaHsSo = _toHocSinhList.Select(h => h.MaHsSo).ToHashSet();
        // HS chưa có tổ = tất cả HS lớp trừ đã có
        _availableHs = _allHsLop
            .Where(h => !assignedMaHsSo.Contains(h.MaHsSo))
            .ToList();

        _showAddHsModal = true;
    }

    private void CloseAddHsModal()
    {
        _showAddHsModal = false;
        _addHsToTarget  = null;
        _selectedHsSet  = new();
    }

    private void ToggleHsSelect(string? maHsSo)
    {
        if (string.IsNullOrEmpty(maHsSo)) return;
        if (_selectedHsSet.Contains(maHsSo)) _selectedHsSet.Remove(maHsSo);
        else _selectedHsSet.Add(maHsSo);
    }

    private async Task ConfirmAddHsToTo()
    {
        if (_addHsToTarget == null || !_selectedHsSet.Any()) return;
        _isSaving = true; StateHasChanged();
        try
        {
            foreach (var maHsSo in _selectedHsSet)
            {
                var hs = _allHsLop.FirstOrDefault(h => h.MaHsSo == maHsSo);
                if (hs == null) continue;
                await TruongService.hUpsertXepHocSinhVaoTo(new ScnToHocSinhDTO
                {
                    Id          = 0,
                    KhoiId      = _selKhoiId,
                    LopId       = _selLopId,
                    MaHsSo      = hs.MaHsSo,
                    HoTen       = hs.HoTen,
                    NgaySinh    = hs.NgaySinh?.ToString("dd/MM/yyyy"),
                    GioiTinh    = hs.MaGioiTinh == "1" ? "Nam" : "Nữ",
                    TenTo       = _addHsToTarget.TenTo,
                    NamHoc      = _selectedNamHoc,
                });
            }
            CloseAddHsModal();
            await LoadData();
            await ShowToast($"Đã thêm {_selectedHsSet.Count} học sinh vào {_addHsToTarget?.TenTo}!", "toast-ok", "check_circle");
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error"); }
        finally { _isSaving = false; StateHasChanged(); }
    }

    private async Task RemoveHsFromTo(ScnToHocSinhDTO hs)
    {
        try
        {
            await TruongService.hDeleteHocSinhTrongTo(hs.Id);
            await LoadData();
            await ShowToast($"Đã xóa {hs.HoTen} khỏi {hs.TenTo}!", "toast-ok", "check_circle");
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error"); }
    }

    // ── TOAST ──
    private async Task ShowToast(string msg, string css, string icon)
    {
        _toastCts?.Cancel();
        _toastCts  = new System.Threading.CancellationTokenSource();
        _toastMsg  = msg; _toastCss = css; _toastIcon = icon;
        StateHasChanged();
        try { await Task.Delay(3500, _toastCts.Token); _toastMsg = ""; StateHasChanged(); }
        catch (TaskCanceledException) {}
    }

